from decimal import Decimal as D

def ex_rights_paid(base, issue_price, ratio):
    return (D(base) + D(issue_price) * D(ratio)) / (1 + D(ratio))

def ex_rights_bonus(base, ratio):
    return D(base) / (1 + D(ratio))

print(ex_rights_paid(10000, 8000, "0.25").quantize(D("1")))  # 9600
print(ex_rights_bonus(57900, 1).quantize(D("1")))            # 28950

ksd  = {"A": 1500, "B": 1050, "C": 450}
ours = {"A": 1500, "B": 1000, "D": 150}
for k in sorted(ksd.keys() | ours.keys()):
    if ksd.get(k) != ours.get(k):
        print(k, ksd.get(k), ours.get(k), "불일치")

